inline int llfsm_check(int value, int lower, int upper, const char *name)
{
    if (value < lower || value > upper) {
        std::cout.flush();
        std::cerr << "range violation " << name << '\n';
        std::exit(2);
    }
    return value;
}

inline std::size_t llfsm_index(int index, int size, const char *name)
{
    return static_cast<std::size_t>(llfsm_check(index, 0, size - 1, name));
}

inline void llfsm_print_bool(bool value)
{
    std::cout << (value ? "true" : "false");
}

inline void llfsm_print_int(int value)
{
    std::cout << value;
}

using Bool = bool;

inline bool llfsm_parse_Bool(const std::string &text, Bool &out)
{
    if (text == "true" || text == "false") {
        out = text == "true";
        return true;
    }
    return false;
}

using Time = int;

inline bool llfsm_parse_Time(const std::string &text, Time &out)
{
    char *end = nullptr;
    errno = 0;
    long value = std::strtol(text.c_str(), &end, 10);
    if (end == text.c_str() || *end != '\0' || errno != 0 || value < 0 || value > 10000) {
        return false;
    }
    out = static_cast<int>(value);
    return true;
}

struct llfsm_Environment {
    Time now{};
    Bool request{};
};

class llfsm_Arrangement;

enum class Crossing_State { Go, Go_x0, Amber, Stop };

inline std::string_view llfsm_name(Crossing_State state)
{
    constexpr std::array<std::string_view, 4> names{{ "Go", "Go_x0", "Amber", "Stop" }};
    return names[static_cast<std::size_t>(state)];
}

inline bool llfsm_is_accepting(Crossing_State state)
{
    constexpr std::array<bool, 4> flags{{ false, false, false, false }};
    return flags[static_cast<std::size_t>(state)];
}

inline bool llfsm_is_pass_through(Crossing_State state)
{
    constexpr std::array<bool, 4> flags{{ false, true, false, false }};
    return flags[static_cast<std::size_t>(state)];
}

struct Crossing_Machine {
    Crossing_State llfsm_pc = Crossing_State::Go;
    bool llfsm_entered = true;
    Time enteredAt{};

    void llfsm_ringlet(llfsm_Arrangement &llfsm_arrangement);
};

class llfsm_Arrangement {
public:
    llfsm_Environment llfsm_environment;
    Crossing_Machine llfsm_instance_main;

    llfsm_Arrangement()
    {
        llfsm_environment.now = 0;
        llfsm_environment.request = false;
        llfsm_instance_main.enteredAt = 0;
    }

    bool llfsm_set_external(const std::string &key, bool indexed, int index, const std::string &value)
    {
        (void)key;
        (void)indexed;
        (void)index;
        (void)value;
        if (key == "now") {
            return !indexed && llfsm_parse_Time(value, llfsm_environment.now);
        }
        if (key == "request") {
            return !indexed && llfsm_parse_Bool(value, llfsm_environment.request);
        }
        return false;
    }

    bool llfsm_apply_assignment(std::string token)
    {
        std::size_t equals = token.find('=');
        if (equals == std::string::npos) {
            return false;
        }
        std::string value = token.substr(equals + 1);
        token.erase(equals);
        bool indexed = false;
        int index = 0;
        std::size_t bracket = token.find('\x5b');
        if (bracket != std::string::npos) {
            const std::string position = token.substr(bracket + 1);
            std::size_t first = (!position.empty() && (position[0] == '+' || position[0] == '-')) ? 1 : 0;
            if (position.size() < first + 2 || position.back() != '\x5d'
                || position.find_first_not_of("0123456789", first) != position.size() - 1) {
                return false;
            }
            errno = 0;
            long parsed = std::strtol(position.c_str(), nullptr, 10);
            if (errno != 0 || parsed < INT_MIN || parsed > INT_MAX) {
                return false;
            }
            index = static_cast<int>(parsed);
            indexed = true;
            token.erase(bracket);
        }
        return llfsm_set_external(token, indexed, index, value);
    }

    bool llfsm_apply_inputs(const std::vector<std::string> &lines, int round)
    {
        for (const std::string &line : lines) {
            std::istringstream fields(line);
            long when = 0;
            if (!(fields >> when) || when != round) {
                continue;
            }
            std::string token;
            while (fields >> token) {
                if (!llfsm_apply_assignment(token)) {
                    std::cerr << "invalid input " << token << '\n';
                    return false;
                }
            }
        }
        return true;
    }

    int llfsm_run(int maxRounds, const std::vector<std::string> &inputLines)
    {
        std::cout << "arrangement CrossingController\n";
        for (int round = 1; ; round++) {
            if (!llfsm_apply_inputs(inputLines, round)) {
                return 1;
            }
            llfsm_instance_main.llfsm_ringlet(*this);
            std::cout << "R" << round << " main " << llfsm_name(llfsm_instance_main.llfsm_pc) << '\n';
            if (llfsm_is_accepting(llfsm_instance_main.llfsm_pc) && !llfsm_instance_main.llfsm_entered) {
                std::cout << "halt R" << round << '\n';
                break;
            }
            if (round == maxRounds) {
                break;
            }
        }
        return 0;
    }
};

void Crossing_Machine::llfsm_ringlet(llfsm_Arrangement &llfsm_arrangement)
{
    const Time now = llfsm_arrangement.llfsm_environment.now;
    const Bool request = llfsm_arrangement.llfsm_environment.request;
    (void)llfsm_arrangement;
    (void)now;
    (void)request;
    for (;;) {
        if (llfsm_entered) {
            llfsm_entered = false;
            switch (llfsm_pc) {
            case Crossing_State::Go:
                enteredAt = llfsm_check(now, 0, 10000, "enteredAt");
                std::cout << "go";
                std::cout << '\n';
                break;
            case Crossing_State::Go_x0:
                std::cout << "clearing";
                std::cout << '\n';
                break;
            case Crossing_State::Amber:
                enteredAt = llfsm_check(now, 0, 10000, "enteredAt");
                std::cout << "amber";
                std::cout << '\n';
                break;
            case Crossing_State::Stop:
                enteredAt = llfsm_check(now, 0, 10000, "enteredAt");
                std::cout << "stop";
                std::cout << '\n';
                break;
            default:
                break;
            }
        }
        bool llfsm_fired = true;
        switch (llfsm_pc) {
        case Crossing_State::Go:
            if (request) {
                llfsm_pc = Crossing_State::Go_x0;
            } else {
                llfsm_fired = false;
            }
            break;
        case Crossing_State::Go_x0:
            if (true) {
                llfsm_pc = Crossing_State::Amber;
            } else {
                llfsm_fired = false;
            }
            break;
        case Crossing_State::Amber:
            if ((now - enteredAt) >= 3) {
                llfsm_pc = Crossing_State::Stop;
            } else {
                llfsm_fired = false;
            }
            break;
        case Crossing_State::Stop:
            if ((now - enteredAt) >= 5) {
                llfsm_pc = Crossing_State::Go;
            } else {
                llfsm_fired = false;
            }
            break;
        default:
            llfsm_fired = false;
            break;
        }
        if (!llfsm_fired) {
            return;
        }
        llfsm_entered = true;
        if (!llfsm_is_pass_through(llfsm_pc)) {
            return;
        }
    }
}

int main(int argc, char **argv)
{
    int maxRounds = argc > 1 ? std::atoi(argv[1]) : 20;
    std::vector<std::string> inputLines;
    if (argc > 2) {
        std::ifstream inputs(argv[2]);
        if (!inputs) {
            std::cerr << "cannot open " << argv[2] << '\n';
            return 1;
        }
        std::string line;
        while (std::getline(inputs, line)) {
            inputLines.push_back(line);
        }
    }
    llfsm_Arrangement arrangement;
    return arrangement.llfsm_run(maxRounds, inputLines);
}
